import base64
from itertools import cycle
from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G
import string

KEYLEN = 12

def catch(f, g, ty=Exception):
    try:
        return f()
    except ty as e:
        return g(e)

topoint = lambda n: point_mul(n, G)
frompoint = lambda p: catch(lambda: list(filter(lambda x: point_equal(p,topoint(x)), range(256)))[0], lambda _: None, StopIteration)
negate = lambda p: (p[0], -p[1], -p[2], p[3])

# Load ciphertext blocks
with open('ciphertext', 'r') as f:
    blocks = f.read().strip().split(';')

# Only keep every 12th block (positions 0,12,24,36,...) for brute-forcing
blocks_key_positions = [[] for _ in range(KEYLEN)]
for i, b in enumerate(blocks):
    blocks_key_positions[i % KEYLEN].append((i, b))

candidates = {}

for kpos, blocklist in enumerate(blocks_key_positions):
    candidates[kpos] = []
    for idx, b64b in blocklist:
        pt = f"Block {idx} (keybyte pos {kpos}): "
        blockbytes = base64.b64decode(b64b)
        ctpoint = point_decompress(blockbytes)
        for keybyte in range(256):
            tb = topoint(keybyte)
            for plain in range(256):
                ptpt = topoint(plain)
                sumpt = point_add(tb, ptpt)
                if point_equal(sumpt, ctpoint):
                    # Check if plausible
                    c = chr(plain)
                    plaus = (c in string.printable) or (idx < 100 and c in 'flag{}')
                    if plaus:
                        pt += f"key={keybyte:02x}/chr={repr(c)} (ascii={plain}); "
                        candidates[kpos].append({'idx': idx, 'key': keybyte, 'chr': c, 'ascii': plain})
        print(pt)

# Show candidate key bytes, group by key position
print('\nLikely candidates by key positions:')
for kpos in range(KEYLEN):
    l = candidates[kpos]
    cnts = {}
    chars = {}
    for aa in l:
        cnts[aa['key']] = cnts.get(aa['key'],0)+1
        chars[aa['key']] = chars.get(aa['key'],[])+[aa['chr']]
    top = sorted(cnts.items(), key=lambda x:x[1], reverse=True)[:10]
    print(f"Key Position {kpos}: Top candidate keybytes:")
    for v,cnt in top:
        print(f"  key={v:02x}, occurrences={cnt}, chars={set(chars[v])}")

# Potentially guess flag using most promising key per position
possible_key = [max(candidates[kpos], key=lambda a:candidates[kpos].count(a))['key'] if candidates[kpos] else 0 for kpos in range(KEYLEN)]
print("\nGuessed key (based on mode per pos):", possible_key)

# Try to decrypt full flag using this key
key_cycle = cycle(possible_key)
flag_blocks = blocks[:len(blocks)] # first N blocks
out = ''
for ctb64, keybyte in zip(flag_blocks, key_cycle):
    ctpoint = point_decompress(base64.b64decode(ctb64))
    found = None
    for plain in range(256):
        ptpt = topoint(plain)
        sumpt = point_add(topoint(keybyte), ptpt)
        if point_equal(sumpt, ctpoint):
            c = chr(plain)
            if c in string.printable:
                out += c
                found = c
                break
    if not found:
        out += '?'
print('\nDecrypted flag guess: ' + out)

