import base64
from itertools import product, islice
from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G
import string
import sys
import time

KEYLEN = 12
FLAG_PREFIX = 'flag{'
FLAG_FORMAT = 'flag{' # for format string

topoint = lambda n: point_mul(n, G)
frompoint = lambda p: next((x for x in range(256) if point_equal(p, topoint(x))), None)
negate = lambda p: (p[0], -p[1], -p[2], p[3])

with open('ciphertext', 'r') as f:
    blocks = f.read().strip().split(';')
cpoints = [point_decompress(base64.b64decode(p)) for p in blocks]

flag_charset = set(string.ascii_letters + string.digits + '{}_-!"@$%^&*()<>:?./,;[]|`~')
def plausible_flag(s):
    return s.startswith(FLAG_PREFIX) and s.endswith('}') and all((x in flag_charset or x == '{' or x == '}') for x in s)

cand_bytes_bykey = {}
for kpos in range(KEYLEN):
    freq = {}
    for bidx in range(kpos, len(cpoints), KEYLEN):
        cpt = cpoints[bidx]
        for k in range(0x20,0x7f):
            try:
                p = point_add(negate(topoint(k)), cpt)
                chrval = frompoint(p)
                if chrval is not None and chr(chrval) in flag_charset:
                    freq.setdefault(k, 0)
                    freq[k] += 1
            except:
                continue
    maxval = max(freq.values()) if freq else 0
    threshold = maxval - 1
    if not freq:
        cand_bytes_bykey[kpos] = list(range(0x20,0x7f))
    else:
        cand_bytes_bykey[kpos] = [k for k,v in freq.items() if v >= threshold]

# Print candidates by key pos
for kpos in range(KEYLEN):
    print(f"Key[{kpos}] candidates: {cand_bytes_bykey[kpos]}")

print("\nKey candidates per position:", [len(cand_bytes_bykey[kpos]) for kpos in range(KEYLEN)])

# Scoring candidate combination across ciphertext
key_tuple_candidates = [cand_bytes_bykey[kpos][:5] for kpos in range(KEYLEN)]  # Top 5 per pos to control compute
flags = set()
num_to_try = 5000000
start_time = time.time()

for idx, ck in enumerate(islice(product(*key_tuple_candidates), num_to_try)):
    kbytes = bytes(ck)
    ptxt = ''
    for i, cpt in enumerate(cpoints):
        k = kbytes[i % KEYLEN]
        try:
            p = point_add(negate(topoint(k)), cpt)
            chrval = frompoint(p)
            c = '?' if chrval is None else chr(chrval)
        except:
            c = '?'
        ptxt += c
    # Find all flag-like substrings
    sidx = 0
    while True:
        start = ptxt.find(FLAG_PREFIX, sidx)
        if start == -1:
            break
        end = ptxt.find('}', start)
        if end == -1:
            break
        flag_str = ptxt[start:end+1]
        if len(flag_str) <= 64 and plausible_flag(flag_str):
            flags.add(flag_str)
        sidx = end+1
    if idx%50000==0 and idx > 0:
        print(f"{idx} keys tested, flags found: {len(flags)}, elapsed: {int(time.time()-start_time)}s")
if not flags:
    print('No plausible flags found in best-key brute set. Try more brute, or candidate sets widen.')
else:
    print('=== Flag candidates ===')
    for f in sorted(flags, key=lambda x: (-len(x), x)):
        print(f)

