# Scoring candidate combination across ciphertext
key_tuple_candidates = [cand_bytes_bykey[kpos][:5] for kpos in range(KEYLEN)]  # Top 5 per pos to control compute
flags = set()
num_to_try = 5000000
start_time = time.time()

