possible_plain = [{} for _ in range(KEYLEN)]   # For each key pos: {key:int: [plain bytes]}
flag_candidates = set()

def ascii_ok(b):
    return 32 <= b <= 126

# Score each key candidate for all positions
def brute_flag_candidates():
    for kpos, blocklist in enumerate(blocks_key_positions):
        for keybyte in range(256):
            valid_bytes = 0
            plausible_plains = []
            for idx, b64b in blocklist:
                ctpt = point_decompress(base64.b64decode(b64b))
                found = False
                for plain in range(256):
                    ptpt = topoint(plain)
                    sumpt = point_add(topoint(keybyte), ptpt)
                    if point_equal(sumpt, ctpt):
                        if ascii_ok(plain):
                            valid_bytes += 1
                            plausible_plains.append((idx,plain))
                        found = True
                        break
            key_candidates[kpos][keybyte] = valid_bytes
            if valid_bytes >= len(blocklist)//2:
                possible_plain[kpos][keybyte] = plausible_plains
    # For each kpos, get best scoring keybytes
    best_keybytes = [max(cands, key=lambda k: cands[k]) for cands in key_candidates]
    # Now try to decrypt the full ciphertext with the best key
    probable_key = bytes(best_keybytes)
    print(f"[*] Best keybyte candidates: {best_keybytes}")
    ptxt_chars = []
    for i, b64b in enumerate(cblocks):
        ctpt = point_decompress(base64.b64decode(b64b))
        k = probable_key[i%KEYLEN]
        # solve for plaintext byte: (ctpt - k)
