import base64
from collections import defaultdict
from itertools import cycle
import string
import sys
sys.path.insert(0, ".")
from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G

KEYLEN = 12
PRINTABLE = set(range(32, 127))  # Printable ASCII

# Load ciphertext
with open("ciphertext", "rt") as f:
    ctxt_blocks = f.read().strip().split(';')

BLOCKS = 5

# Topoint/negate/frompoint helpers
catch = lambda f, g, ty=Exception: (lambda: (f(), None))[0] if not (e := None) else (None, g(e))
topoint = lambda n: point_mul(n, G)
def frompoint(p):
    try:
        for x in range(256):
            if point_equal(p, topoint(x)):
                return x
    except Exception:
        pass
    return None
def negate(p):
    return (p[0], -p[1], -p[2], p[3])

# Build [points] for [BLOCKS] ciphertexts
cipherpoints = [point_decompress(base64.b64decode(c)) for c in ctxt_blocks[:BLOCKS]]

# Store all candidate key_byte per position that yield printable plaintext for all 5 blocks
pos_candidates = [defaultdict(set) for _ in range(KEYLEN)]

for b in range(BLOCKS):
    for pos in range(KEYLEN):
        pt = cipherpoints[b]
        # For this block and position, try all possible key_byte
        for k in range(256):
            try:
                keypt = topoint(k)
                # y = ENC = point_add(keypt, plainpt). So pt = ENC
                # For each candidate printable plaintext byte
                for c in PRINTABLE:
                    ptpt = topoint(c)
                    z = point_add(negate(keypt), pt)
                    maybe_c = frompoint(z)
                    if maybe_c == c:
                        # For this pos & b, k could yield c
                        pos_candidates[pos][k].add(c)
            except Exception:
                pass
# For each position, filter key_bytes that yielded printable across all BLOCKS
summary_candidates = {}
for pos in range(KEYLEN):
    consistent_keys = [k for k in pos_candidates[pos] if len(pos_candidates[pos][k]) == len(PRINTABLE)]
    likely_keys = [k for k in pos_candidates[pos] if len(pos_candidates[pos][k]) > 0]
    summary_candidates[pos] = {
        'consistent_printable_across_blocks': consistent_keys,
        'candidate_key_bytes': sorted(likely_keys),
        'n_candidates': len(likely_keys)
    }

from pprint import pprint
pprint(summary_candidates)

